let api,config,isAdmin=false,signup=false,authKind='login',filter='all',topics=[],page=0,hasMore=false,currentTopic=null,repliesPage=0,routeVersion=0,forumReady=false,authNoticeKey='',indexGroups=[],indexCards=[];
