function node(tag,text,className){const element=document.createElement(tag);if(text!==undefined)element.textContent=text;if(className)element.className=className;return element}
const categoryIcon={general:'message',builds:'grid',help:'help',suggestions:'idea'};
function icon(name){
 const paths={message:'<path d="M22 17a2 2 0 0 1-2 2H6.828a2 2 0 0 0-1.414.586l-2.202 2.202A.71.71 0 0 1 2 21.286V5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2z"/>',grid:'<rect width="7" height="7" x="3" y="3" rx="1"/><rect width="7" height="7" x="14" y="3" rx="1"/><rect width="7" height="7" x="14" y="14" rx="1"/><rect width="7" height="7" x="3" y="14" rx="1"/>',help:'<circle cx="12" cy="12" r="10"/><path d="M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3"/><path d="M12 17h.01"/>',idea:'<path d="M15 14c.2-1 .7-1.7 1.5-2.5 1-.9 1.5-2.2 1.5-3.5A6 6 0 0 0 6 8c0 1 .2 2.2 1.5 3.5.7.7 1.3 1.5 1.5 2.5"/><path d="M9 18h6"/><path d="M10 22h4"/>',lock:'<rect width="18" height="11" x="3" y="11" rx="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/>',empty:'<polyline points="22 12 16 12 14 15 10 15 8 12 2 12"/><path d="M5.45 5.11 2 12v6a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2v-6l-3.45-6.89A2 2 0 0 0 16.76 4H7.24a2 2 0 0 0-1.79 1.11z"/>',plus:'<path d="M5 12h14"/><path d="M12 5v14"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2"/><path d="M12 20v2"/><path d="m4.93 4.93 1.41 1.41"/><path d="m17.66 17.66 1.41 1.41"/><path d="M2 12h2"/><path d="M20 12h2"/><path d="m6.34 17.66-1.41 1.41"/><path d="m19.07 4.93-1.41 1.41"/>',moon:'<path d="M12 3a6 6 0 0 0 9 9 9 9 0 1 1-9-9Z"/>',pin:'<path d="M12 17v5"/><path d="M9 10.76a2 2 0 0 1-1.11 1.79l-1.78.9A2 2 0 0 0 5 15.24V16a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1v-.76a2 2 0 0 0-1.11-1.79l-1.78-.9A2 2 0 0 1 15 10.76V7a1 1 0 0 1 1-1 2 2 0 0 0 0-4H8a2 2 0 0 0 0 4 1 1 0 0 1 1 1z"/>'};
 const holder=document.createElement('template');holder.innerHTML='<svg viewBox="0 0 24 24" class="icon" aria-hidden="true">'+paths[name]+'</svg>';return holder.content.firstElementChild;
}
function notice(message=''){ $('notice').textContent=message;$('notice').hidden=!message; }
function saveSession(value){
 const changed=session?.user?.id!==value?.user?.id;session=value;
 if(changed){routeVersion++;topics=[];currentTopic=null;isAdmin=false;$('adminNav').hidden=true;$('adminContent').hidden=true;
  for(const id of ['topicList','topicDetail','replies','friendList','friendSelect'])$(id).replaceChildren();
  $('ownerForm').elements.notes.value='';$('privateNameForm').elements.name.value='';$('ownerIdentity').textContent='';$('replyForm').hidden=true;$('topicDialog').close();
 }
 if(value){sessionStorage.setItem('faf-session',JSON.stringify(value));anonymousMode=false;sessionStorage.removeItem('faf-anonymous')}
 else sessionStorage.removeItem('faf-session');updateAccount();
}
function updateAccount(){ $('accountButton').textContent=t(session?'logout':'login');$('registerButton').hidden=Boolean(session);$('identityStatus').textContent=!session&&anonymousMode?t('anonymousActive'):'';$('identityStatus').hidden=Boolean(session)||!anonymousMode;const heroLabel=$('heroJoinLabel');if(heroLabel)heroLabel.textContent=t(session?'newTopic':'register'); }
function categoryLabel(id){const board=indexCards.find(item=>item.id===id);return board?label(board,lang):t(id)}
function boardIcon(id){return indexCards.find(item=>item.id===id)?.icon||categoryIcon[id]||'message'}
function missingTable(error){return /404|PGRST205|does not exist|schema cache/i.test(String(error?.message||''))}
function friendlyWrite(error){if(/foreign key|23503/i.test(String(error?.message||'')))throw Error(t('stillHasChildren'));throw error}
function renderCrumbs(el,items){if(!el)return;el.replaceChildren();items.forEach((item,index)=>{if(index)el.append(node('span','/','crumb-sep'));if(item.href){const link=node('a',item.label);link.href=item.href;el.append(link)}else el.append(node('span',item.label,'current'))})}
function paintBoardChrome(){const board=indexCards.find(item=>item.id===filter);const title=$('boardTitle'),note=$('boardNote');if(title)title.textContent=board?label(board,lang):t('topicsHeading');if(note)note.textContent=board?(blurb(board,lang)||t('latest')):t('latest');const group=board?indexGroups.find(item=>item.id===board.group_id)||{name_de:board.group_name_de,name_en:board.group_name_en}:null;renderCrumbs($('boardCrumbs'),crumbItems({forumLabel:t('forum'),group:group?{label:label(group,lang)}:null,board:board?{id:board.id,label:label(board,lang)}:null}))}
function paintTopicChrome(){const board=currentTopic&&indexCards.find(item=>item.id===currentTopic.category_id);const group=board?indexGroups.find(item=>item.id===board.group_id)||{name_de:board.group_name_de,name_en:board.group_name_en}:null;renderCrumbs($('topicCrumbs'),crumbItems({forumLabel:t('forum'),group:group?{label:label(group,lang)}:null,board:board?{id:board.id,label:label(board,lang)}:null,topic:currentTopic?{label:currentTopic.title}:null}))}
function fillCategoryControls(){if(!$('categoryNav'))return;$('categoryNav').replaceChildren();$('topicCategory').replaceChildren();$('categoryFilter').replaceChildren();const all=node('option',t('allTopics'));all.value='all';$('categoryFilter').append(all);const list=indexCards.length?indexCards:categories.map(id=>({id}));list.forEach(board=>{const id=board.id;const link=document.createElement('a');link.href='#board/'+id;link.className='pill';const dot=document.createElement('span');dot.className='dot dot-'+id;link.append(dot,icon(board.icon||categoryIcon[id]||'message'),document.createTextNode(categoryLabel(id)));link.classList.toggle('active',filter===id);if(filter===id)link.setAttribute('aria-current','page');$('categoryNav').append(link);const option=node('option',categoryLabel(id));option.value=id;$('topicCategory').append(option);const filterOption=node('option',categoryLabel(id));filterOption.value=id;$('categoryFilter').append(filterOption)});if([...$('categoryFilter').options].some(option=>option.value===filter))$('categoryFilter').value=filter}
function latestBlock(card){const wrap=node('div',undefined,'board-latest');if(!card.latest_title){wrap.append(node('span',t('noActivity')));return wrap}wrap.append(node('strong',card.latest_title));const bits=[];if(card.latest_author)bits.push(authorName(card.latest_author,lang));if(card.latest_at)bits.push(relativeTime(card.latest_at));if(bits.length)wrap.append(node('span',bits.join(' · ')));return wrap}
function renderIndex(){const root=$('forumIndex');if(!root)return;root.replaceChildren();const ordered=[...indexGroups].sort((a,b)=>a.position-b.position||String(a.id).localeCompare(String(b.id)));if(!ordered.length){root.append(empty(t('empty'),t('emptyNote')));return}ordered.forEach(group=>{const section=node('section',undefined,'group-block');section.id='group-'+group.id;const head=node('div',undefined,'group-head');head.append(node('h2',label(group,lang)));const desc=blurb(group,lang);if(desc)head.append(node('p',desc));section.append(head);const mine=indexCards.filter(card=>(card.group_id||'community')===group.id).sort((a,b)=>a.position-b.position||String(a.id).localeCompare(String(b.id)));if(!mine.length)section.append(node('p',t('noBoards'),'muted group-empty'));mine.forEach(card=>{const link=document.createElement('a');link.className='board-card';link.href='#board/'+card.id;const mark=node('div',undefined,'board-mark');mark.append(icon(card.icon||categoryIcon[card.id]||'message'));const copy=node('div',undefined,'board-copy');copy.append(node('h3',label(card,lang)));const text=blurb(card,lang);if(text)copy.append(node('p',text));const counts=node('div',undefined,'board-counts');const threads=Number(card.thread_count)||0,posts=Number(card.post_count)||0;counts.append(node('span',threads+' '+t(threads===1?'threadOne':'threadMany')),node('span',posts+' '+t(posts===1?'postOne':'postMany')));link.append(mark,copy,counts,latestBlock(card));section.append(link)});root.append(section)})}
async function loadPlainBoards(){try{const rows=await api.db('forum_categories?select=id,position,group_id,name_de,name_en,description_de,description_en,icon&order=position.asc,id.asc');return rows.map(row=>({...row,group_id:row.group_id||'community',name_de:row.name_de||row.id,name_en:row.name_en||row.id,description_de:row.description_de||'',description_en:row.description_en||'',icon:row.icon||categoryIcon[row.id]||'message',thread_count:0,post_count:0}))}catch{const rows=await api.db('forum_categories?select=id,position&order=position.asc,id.asc');return fallbackIndex(rows.map(row=>row.id)).boards}}
async function ensureCatalog(version){let groups=null,cards=null;try{groups=await api.db('forum_groups?select=id,position,name_de,name_en,description_de,description_en&order=position.asc,id.asc')}catch{groups=null}if(version!==routeVersion)return;try{cards=await api.db('forum_board_cards?select=id,position,group_id,name_de,name_en,description_de,description_en,icon,group_position,group_name_de,group_name_en,group_description_de,group_description_en,thread_count,post_count,latest_id,latest_title,latest_author_id,latest_at&order=group_position.asc,position.asc,id.asc')}catch{cards=null}if(!cards){try{cards=await loadPlainBoards()}catch{cards=null}}if(!groups||!cards){const fallback=fallbackIndex(cards?.length?cards.map(card=>card.id):categories);if(!groups)groups=fallback.groups;if(!cards)cards=fallback.boards}if(version!==routeVersion)return;try{const named=await attachNames(cards.filter(card=>card.latest_author_id).map(card=>({author_id:card.latest_author_id})));const byId=new Map(named.map(row=>[row.author_id,row.author]));cards.forEach(card=>{card.latest_author=byId.get(card.latest_author_id)||null})}catch{/* The board list still renders when author names are unavailable. */}if(version!==routeVersion)return;indexGroups=groups;indexCards=cards;syncCategories(categories,cards.map(card=>card.id));renderIndex();forumReady=cards.length>0}
function fillGroupForm(row){const form=$('groupForm');form.elements.id.value=row?.id||'';form.elements.id.readOnly=Boolean(row);form.elements.position.value=row?.position||1;form.elements.name_de.value=row?.name_de||'';form.elements.name_en.value=row?.name_en||'';form.elements.description_de.value=row?.description_de||'';form.elements.description_en.value=row?.description_en||''}
function fillBoardForm(row){const form=$('boardForm');form.elements.id.value=row?.id||'';form.elements.id.readOnly=Boolean(row);form.elements.position.value=row?.position||1;if(row?.group_id)form.elements.group_id.value=row.group_id;form.elements.name_de.value=row?.name_de||'';form.elements.name_en.value=row?.name_en||'';form.elements.description_de.value=row?.description_de||'';form.elements.description_en.value=row?.description_en||'';form.elements.icon.value=boardIcons.includes(row?.icon)?row.icon:'message'}
function fillBoardGroups(groups){const select=$('boardGroup'),current=select.value;select.replaceChildren();groups.forEach(group=>{const option=node('option',label(group,lang));option.value=group.id;select.append(option)});if([...select.options].some(option=>option.value===current))select.value=current}
function renderStructureLists(groups,boards){$('groupList').replaceChildren();groups.forEach(group=>{const row=node('div',undefined,'friend-row');row.append(node('span',label(group,lang)+' · '+group.id));const actions=node('div',undefined,'row-actions');const edit=node('button',t('edit'),'outline');edit.type='button';edit.onclick=()=>fillGroupForm(group);const remove=node('button',t('remove'),'danger');remove.type='button';remove.onclick=()=>{if(!confirm(t('confirmDeleteGroup')))return;run(row,async()=>{try{await api.db('forum_groups?id=eq.'+encodeURIComponent(group.id),{method:'DELETE'})}catch(error){friendlyWrite(error)}await loadStructureAdmin();notice(t('saved'))})};actions.append(edit,remove);row.append(actions);$('groupList').append(row)});$('boardList').replaceChildren();boards.forEach(board=>{const row=node('div',undefined,'friend-row');row.append(node('span',label(board,lang)+' · '+board.id));const actions=node('div',undefined,'row-actions');const edit=node('button',t('edit'),'outline');edit.type='button';edit.onclick=()=>fillBoardForm(board);const remove=node('button',t('remove'),'danger');remove.type='button';remove.onclick=()=>{if(!confirm(t('confirmDeleteBoard')))return;run(row,async()=>{try{await api.db('forum_categories?id=eq.'+encodeURIComponent(board.id),{method:'DELETE'})}catch(error){friendlyWrite(error)}await loadStructureAdmin();notice(t('saved'))})};actions.append(edit,remove);row.append(actions);$('boardList').append(row)})}
async function loadStructureAdmin(){const groups=await api.db('forum_groups?select=*&order=position.asc,id.asc');const boards=await api.db('forum_categories?select=*&order=position.asc,id.asc');fillBoardGroups(groups);renderStructureLists(groups,boards)}
function date(value){return new Intl.DateTimeFormat(lang,{dateStyle:'medium',timeStyle:'short'}).format(new Date(value))}
function relativeTime(value){
 const then=new Date(value).getTime();if(Number.isNaN(then))return '';
 const delta=then-Date.now(),abs=Math.abs(delta);
 if(abs<45000)return lang==='de'?'gerade eben':'just now';
 const steps=[['year',31557600000],['month',2629800000],['week',604800000],['day',86400000],['hour',3600000],['minute',60000]];
 let unit='minute',size=60000;
 for(const [name,ms] of steps)if(abs>=ms){unit=name;size=ms;break}
 return new Intl.RelativeTimeFormat(lang,{numeric:'auto'}).format(Math.round(delta/size),unit);
}
function tone(name){let hash=0;for(const ch of name)hash=(hash*31+ch.charCodeAt(0))>>>0;return 'tone-'+(hash%6)}
function replyCount(topic){const embedded=topic.forum_replies;if(!Array.isArray(embedded)||!embedded.length)return null;const value=Number(embedded[0]?.count);return Number.isFinite(value)?value:null}
let theme=localStorage.getItem('faf-theme')==='light'?'light':'dark';
function applyTheme(){
 if(theme==='light')document.documentElement.dataset.theme='light';else document.documentElement.removeAttribute('data-theme');
 localStorage.setItem('faf-theme',theme);
 const meta=document.querySelector('meta[name=theme-color]');if(meta)meta.setAttribute('content',theme==='light'?'#fafafa':'#09090b');
 const toggle=$('themeToggle');if(!toggle)return;
 toggle.setAttribute('aria-pressed',String(theme==='light'));
 toggle.setAttribute('aria-label',theme==='light'?(lang==='de'?'Dunkles Design verwenden':'Use dark theme'):(lang==='de'?'Helles Design verwenden':'Use light theme'));
 toggle.replaceChildren(icon(theme==='light'?'moon':'sun'));
}
