function empty(title,body,retry=false){if(title===t('loading'))return node('p',title,'muted loading');const el=node('div',undefined,'empty'),mark=node('div',undefined,'empty-mark');mark.append(icon(retry?'help':'empty'));el.append(mark,node('h3',title));if(body)el.append(node('p',body));if(retry){const button=node('button',t('retry'),'secondary');button.type='button';button.onclick=()=>loadTopics(true);el.append(button)}else if(title===t('empty')){const button=node('button',undefined,'primary');button.type='button';button.append(icon('plus'),node('span',t('newTopic')));button.onclick=()=>$('newTopic').click();el.append(button)}return el}
async function run(form,fn,messageTarget){const buttons=[...form.querySelectorAll('button[type=submit],button:not([type])')];buttons.forEach(b=>b.disabled=true);if(messageTarget)messageTarget.textContent='';try{await fn()}catch(error){if(messageTarget)messageTarget.textContent=error.message;else notice(t('error')+error.message)}finally{buttons.forEach(b=>b.disabled=false)}}
function siteKey(){return config?.security?.turnstileSiteKey||''}
function resetCaptcha(){captchaToken='';if(turnstileWidget&&window.turnstile)window.turnstile.reset(turnstileWidget)}
function renderTurnstile(){if(!siteKey()||!window.turnstile||!$('turnstileSlot'))return;const slot=$('turnstileSlot');slot.hidden=false;if(turnstileWidget){window.turnstile.remove(turnstileWidget);turnstileWidget=null}captchaToken='';turnstileWidget=window.turnstile.render(slot,{sitekey:siteKey(),theme:theme==='light'?'light':'dark',language:lang==='en'?'en':'de',callback:token=>{captchaToken=token},'expired-callback':()=>{captchaToken=''},'error-callback':()=>{captchaToken=''}})}
function mountCaptcha(){if(!siteKey()){$('turnstileSlot').hidden=true;return}if(window.turnstile){renderTurnstile();return}turnstileLoading??=new Promise((resolve,reject)=>{window.fafTurnstileReady=()=>resolve();const script=document.createElement('script');script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit&onload=fafTurnstileReady';script.async=true;script.onerror=()=>reject(Error(t('captchaUnavailable')));document.head.append(script)});turnstileLoading.then(()=>renderTurnstile()).catch(error=>{turnstileLoading=null;$('authMessage').textContent=error.message})}
