$('ownerForm').onsubmit=event=>{event.preventDefault();run(event.target,async()=>{const rows=await api.db('forum_owner_settings?id=eq.1',{method:'PATCH',body:{notes:event.target.elements.notes.value}});if(!rows.length)throw Error(t('settingsRequired'));notice(t('saved'))})};
let searchTimer;$('search').oninput=()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{routeVersion++;loadTopics(true)},300)};
$('loadMore').onclick=()=>{page++;run($('forumView'),()=>loadTopics(false))};$('moreReplies').onclick=()=>{run($('topicView'),()=>loadReplies(false,true))};
$('anonymousButton').onclick=()=>run($('authForm'),async()=>{if(siteKey()&&!captchaToken)throw Error(t('captchaRequired'));const token=captchaToken;try{if(token){try{const result=await api.signInAnonymously(token);if(result?.access_token){$('authDialog').close();await adminCheck();await route();return}}catch(error){if(!/anonymous/i.test(error.message||''))throw error}}if(session)try{await api.logout()}finally{await route()}anonymousMode=true;sessionStorage.setItem('faf-anonymous','1');updateAccount();$('authDialog').close();await route()}finally{if(token)resetCaptcha()}},$('authMessage'));
$('privateNameForm').onsubmit=event=>{event.preventDefault();run(event.target,async()=>{await api.db('rpc/forum_set_owner_name',{method:'POST',body:{p_name:event.target.elements.name.value}});notice(t('saved'))})};
$('friendForm').onsubmit=event=>{event.preventDefault();run(event.target,async()=>{const id=$('friendSelect').value;if(!id)return;await api.db('rpc/forum_set_friend',{method:'POST',body:{p_friend:id,p_allow:true}});await loadFriends();notice(t('saved'))})};
$('copyAddress').onclick=async()=>{try{await navigator.clipboard.writeText(config.server.address);notice(t('copied'))}catch{notice(config.server.address)}};
$('categoryFilter').onchange=event=>{location.hash=event.target.value==='all'?'forum':'board/'+event.target.value};
function watchSlug(form){form.elements.id.addEventListener('input',()=>{if(!form.elements.id.readOnly)form.elements.id.value=form.elements.id.value.toLowerCase()})}
watchSlug($('groupForm'));watchSlug($('boardForm'));
$('groupReset').onclick=()=>fillGroupForm(null);
$('boardReset').onclick=()=>fillBoardForm(null);
$('groupForm').onsubmit=event=>{event.preventDefault();run(event.target,async()=>{const form=event.target.elements;const body={id:structureId(form.id.value),position:structurePosition(form.position.value),name_de:boundedText(form.name_de.value,2,80),name_en:boundedText(form.name_en.value,2,80),description_de:boundedText(form.description_de.value,0,400),description_en:boundedText(form.description_en.value,0,400)};if(form.id.readOnly){const rows=await api.db('forum_groups?id=eq.'+encodeURIComponent(body.id),{method:'PATCH',body:{position:body.position,name_de:body.name_de,name_en:body.name_en,description_de:body.description_de,description_en:body.description_en}});if(!rows.length)throw Error(t('settingsRequired'))}else await api.db('forum_groups',{method:'POST',body});fillGroupForm(null);await loadStructureAdmin();notice(t('saved'))})};
$('boardForm').onsubmit=event=>{event.preventDefault();run(event.target,async()=>{const form=event.target.elements;if(!boardIcons.includes(form.icon.value))throw Error(t('iconLabel'));const body={id:structureId(form.id.value),position:structurePosition(form.position.value),group_id:structureId(form.group_id.value),name_de:boundedText(form.name_de.value,2,80),name_en:boundedText(form.name_en.value,2,80),description_de:boundedText(form.description_de.value,0,400),description_en:boundedText(form.description_en.value,0,400),icon:form.icon.value};if(form.id.readOnly){const rows=await api.db('forum_categories?id=eq.'+encodeURIComponent(body.id),{method:'PATCH',body:{position:body.position,group_id:body.group_id,name_de:body.name_de,name_en:body.name_en,description_de:body.description_de,description_en:body.description_en,icon:body.icon}});if(!rows.length)throw Error(t('settingsRequired'))}else await api.db('forum_categories',{method:'POST',body});fillBoardForm(null);await loadStructureAdmin();notice(t('saved'))})};
async function consumeAuthHash(){
 const returned=authReturn(location.href);if(!returned)return false;
 history.replaceState(null,'',returned.href);
 let failure='';
 if(returned.session&&api){try{await api.useSession(returned.session)}catch(error){failure=error.message}}
 authNoticeKey=failure?'':returned.error?'authLinkInvalid':returned.confirmation?(returned.session&&session?'emailConfirmedIn':'emailConfirmed'):'';
 if(failure)notice(failure);
 return !failure;
}
const authLanding=authReturn(location.href);
if(authLanding)history.replaceState(null,'',authLanding.href);
window.addEventListener('hashchange',async()=>{if(await consumeAuthHash())return route(Boolean(authNoticeKey));authNoticeKey='';route()});
applyLanguage();
try{
 const responses=await Promise.all([fetch('assets/data/supabase.json'),fetch('assets/data/config.json')]);if(responses.some(response=>!response.ok))throw Error('Configuration unavailable');const [connection,settings]=await Promise.all(responses.map(r=>r.json()));config=settings;api=createApi(connection,()=>session,saveSession);renderConfig();let authFailure='';try{if(authLanding?.session)await api.useSession(authLanding.session);else await api.session()}catch(error){authFailure=error.message}await adminCheck();if(!authFailure&&authLanding?.error)authNoticeKey='authLinkInvalid';else if(!authFailure&&authLanding?.confirmation)authNoticeKey=authLanding.session&&session?'emailConfirmedIn':'emailConfirmed';await route(Boolean(authNoticeKey));if(authFailure)notice(authFailure);if(config.server.address)setInterval(checkServer,Math.max(60,config.server.refreshSeconds||120)*1000);
}catch(error){notice(t('error')+error.message);$('topicList').replaceChildren(empty(t('unavailable'),t('setup')));$('accountButton').disabled=true;$('newTopic').disabled=true;$('heroJoin').disabled=true}
